#include<bits/stdc++.h>

using namespace std;

const int M = 1e3 + 5;
const double eps = 1e-8;

int sgn(double x){
    if(fabs(x) < eps)return 0;
    if(x < 0)return -1;
    else return 1;
}

struct Point{
    double x, y;

    void input(){
        scanf("%lf%lf",&x,&y);
    }
    Point(){}
    Point(double _x, double _y){
        x = _x, y = _y;
    }

    double operator^ (const Point &b)const{
        return x * b.y - y * b.x;
    }

    double operator* (const Point &b)const{
        return x * b.x + y * b.y;
    }

    Point operator -(const Point &b)const{
        return Point(x-b.x,y-b.y);
    }
};

struct Line {
    Point s, e;

    void input(){
        s.input();
        e.input();
    }

    Point crosspoint(Line v){
        double a1 = (v.e - v.s)^(s - v.s);
        double a2 = (v.e - v.s)^(e - v.s);
        return Point((s.x * a2 - e.x * a1) / (a2 - a1), (s.y * a2 - e.y * a1) / (a2 - a1));
    }//求两直线交点

    bool isone() {
        return (e.y - s.y) / (e.x - s.x) > 0;
    }//判断斜率是1还是-1,1为true,-1为false
};


int h, w;

void solve() {
    cin >> h >> w;
    int m;
    cin >> m;
    vector<Line> v1, v2;//v1存斜率为1的直线，v2存斜率为-1的直线
    Line l;
    for (int i = 1; i <= m; i++) {
        l.input();
        if (l.isone()) v1.push_back(l);
        else v2.push_back(l);
    }
    int ans = v1.size() + 1;//初始化为斜率为1的直线的个数加一
    for (int i = 0; i < v2.size(); i++) {
        int cnt = 1;//必会产生新矩形
        for (int j = 0; j < v1.size(); j++) {
            Point p = v2[i].crosspoint(v1[j]);
            if (p.x < w && p.x > 0 && p.y < h && p.y > 0) {//判断交点是否在矩形内,记录这类交点个数
                cnt++;
            }
        }
        ans += cnt;
    }
    cout << ans << endl;
}

int main() {
    int t = 1;
    // cin >> t;
    while (t--) solve();
    return 0;
}
